const std = @import("std");

const Point = struct { x: i32, y: i32 };

pub fn main() !void {
    const points = [_]Point{
        Point{ .x = 0, .y = 3 },
        Point{ .x = 2, .y = 2 },
        Point{ .x = 1, .y = 1 },
        Point{ .x = 2, .y = 1 },
        Point{ .x = 3, .y = 0 },
        Point{ .x = 0, .y = 0 },
        Point{ .x = 3, .y = 3 },
    };

    var leftmost: usize = 0;
    for (1..points.len) |i| {
        if (points[i].x < points[leftmost].x) leftmost = i;
    }

    var hull: [7]Point = undefined;
    var hull_size: usize = 0;
    var p = leftmost;

    while (true) {
        hull[hull_size] = points[p];
        hull_size += 1;
        var q: usize = (p + 1) % points.len;
        for (0..points.len) |i| {
            const cross = (points[i].x - points[p].x) * (points[q].y - points[p].y) -
                          (points[i].y - points[p].y) * (points[q].x - points[p].x);
            if (cross < 0) q = i;
        }
        p = q;
        if (p == leftmost) break;
    }

    for (0..hull_size) |i| std.debug.print("({},{}) ", .{hull[i].x, hull[i].y});
    std.debug.print("\n", .{});
}

